function* g(): Generator<any, void, unknown> {
  try { yield 1; } catch (error) { yield error; }
}
function main(): void {
  const it = g();
  it.next();
  console.log(it.throw(7).value);
  const it2 = g();
  it2.next();
  console.log(it2.throw("s").value);
  const it3 = g();
  it3.next();
  console.log(it3.throw(undefined).value);
}
